REG={
'demacia':("Một vương quốc rực rỡ dựng trên luật pháp, thép và nỗi sợ sâu sắc với phép thuật.","Demacia bao quanh mình bằng petricite, loại đá trắng làm suy yếu phép thuật, và người dân được dạy rằng pháp sư là nguy hiểm. Quy tắc ấy đang rạn nứt, và vài anh hùng của chính vương quốc đang giấu thứ sức mạnh mà nó săn lùng."),
'noxus':("Một đế chế chấp nhận bất kỳ ai, miễn là chứng tỏ được sức mạnh.","Noxus lớn lên nhờ chinh phạt, nhưng chẳng quan tâm bạn sinh ra ở đâu. Ai đủ mạnh cũng có thể vươn lên. Sau lưng các tướng quân, những thế lực cũ như Hoa Hồng Đen vẫn tranh giành xem ai mới thật sự giật dây."),
'piltover':("Thành phố của Tiến bộ, nơi công nghệ hextech tạo nên những gia tài.","Piltover nắm giữ kênh đào thương mại giữa hai lục địa và giàu lên nhờ nó. Hextech, sự kết hợp giữa phép thuật và kỹ thuật, khiến các nhà phát minh của thành phố nổi danh. Sự giàu có ấy nằm ngay trên đầu Zaun, và không thành phố nào quên điều đó."),
'zaun':("Thành phố ngầm dưới Piltover, ngột ngạt vì hóa kỹ và tham vọng.","Zaun sống trong làn khói bên dưới những tòa tháp sáng choang của Piltover. Các trùm hóa chất cai quản đường phố, hóa kỹ giữ cho thành phố sống sót, và người dân vì thế mà cứng cỏi, kỳ lạ hơn. Jinx, Ekko và Viktor đều đến từ đây."),
'freljord':("Vùng đất băng giá của các bộ tộc đối địch và những vị thần cổ bị chôn vùi.","Freljord là phương bắc khắc nghiệt và lạnh giá, chia rẽ giữa các bộ tộc đang giao chiến. Ba trong số đó do những người phụ nữ lãnh đạo, đòi quyền cai trị cổ xưa. Dưới lớp băng, những Kẻ Canh Giữ đang chờ được đánh thức."),
'ionia':("Hòn đảo của phép thuật tâm linh, vẫn đang hồi phục sau cuộc xâm lược của Noxus.","Ionia là vùng đất nơi thiên nhiên và linh hồn sống cạnh nhau. Noxus xâm lược và bị đẩy lùi, nhưng chiến tranh chia rẽ người Ionia trước một câu hỏi khó: tiếp tục ôn hòa hay trở nên tàn nhẫn như kẻ thù?"),
'shurima':("Một đế chế sa mạc sụp đổ, nay vị hoàng đế đã trỗi dậy lần nữa.","Shurima từng cai trị phần lớn thế giới với các chiến binh Thăng Hoa mang sức mạnh thần thánh. Rồi đế chế sụp đổ vì bị phản bội từ bên trong. Giờ hoàng đế Azir đã trở về từ cát bụi, và những mối thù cũ cũng thức tỉnh theo ông."),
'targon':("Ngọn núi chạm tới các vì sao, nơi thần linh chọn vật chủ phàm trần.","Núi Targon cao đến mức như chạm vào bầu trời. Những ai lên được đỉnh có thể được chọn bởi một Thượng Nhân, sinh thể thiên giới nhập vào một vật chủ phàm trần. Bên dưới, những kẻ thờ mặt trời và mặt trăng đã giao chiến hàng thế kỷ."),
'bilgewater':("Hải cảng vô luật của hải tặc, quái vật và nợ nần.","Bilgewater là thành phố cảng không có chính quyền thực sự, chỉ có thuyền trưởng, băng đảng và quái vật biển. Giàu sang và cái chết luôn chỉ cách nhau một vụ làm ăn tồi. Vua hải tặc cũ đã ngã xuống, và một nữ thuyền trưởng mới đang làm chủ bến cảng."),
'shadowisles':("Những hòn đảo từng được ban phước, nay chìm trong Màn Sương Đen.","Quần Đảo Phước Lành từng là nơi chữa lành, cho đến khi một vị vua đau buồn cố hồi sinh người vợ đã khuất. Phép thuật vỡ vụn và Màn Sương Đen nuốt chửng tất cả. Giờ người chết ở đó không thể yên nghỉ và vẫn đang lan rộng."),
'bandle':("Quê nhà của người Yordle, chỉ những ai được cho vào mới tìm thấy.","Thành phố Bandle nằm một nửa trong cõi linh hồn, và lối vào luôn dịch chuyển. Người Yordle nhỏ bé, đầy phép thuật và tò mò vô tận. Họ lang thang khắp thế giới và thường biết nhiều hơn những gì họ thể hiện. Tải lại trang, cánh cổng sẽ ở chỗ khác."),
'ixtal':("Vương quốc ẩn mình trong rừng rậm của các pháp sư nguyên tố.","Ixtal rút sâu vào rừng rậm trong các cuộc Chiến tranh Cổ Ngữ và sống tách biệt với thế giới từ đó. Những người cai trị điều khiển các nguyên tố, và rừng của họ là nơi ở của vài thợ săn chết chóc nhất."),
'void':("Một hư vô đói khát đang đè lên từ bên dưới thế giới.","Hư Không không hẳn là một nơi mà là một cơn đói. Nó xé toạc ra ở Icathia từ thời xa xưa và từ đó luôn tìm cách xóa sổ Runeterra. Sinh vật của nó thích nghi, nuốt chửng, và vài kẻ học được cách suy nghĩ."),
'wanderers':("Thần linh, quái vật và lữ khách không thuộc về quốc gia nào.","Không phải huyền thoại nào cũng có quê hương. Vài kẻ còn cổ xưa hơn cả các quốc gia, như tộc Darkin và họ hàng sa ngã của các Thượng Nhân. Số khác lang thang giữa các vương quốc, canh giữ những cổ ngữ đã tạo nên thế giới, hoặc đơn giản là săn mồi nơi họ muốn. Họ xuất hiện trong câu chuyện của mọi vùng đất mà không thuộc về nơi nào."),
}
